SELECT i.id, i.user_id, u.username, u.nickname, i.order_id, o.order_no, i.product_id, i.product_name, i.address, i.contact_name, i.contact_phone, i.expected_time, i.confirmed_time, i.engineer_name, i.engineer_phone, i.user_remark, i.admin_remark, i.status, i.admin_id, i.create_time, i.update_time FROM tb_installation i LEFT JOIN tb_order o ON i.order_id = o.id LEFT JOIN tb_user u ON i.user_id = u.id WHERE 1 = 1
AND i.status = #{status}
AND i.create_time >= #{startTime}
AND i.create_time <= #{endTime}
ORDER BY i.create_time DESC
